cases.script:
strip() { /usr/bin/sed -E 's/^[^:]*: line [0-9]+: //' "$1" | /usr/bin/tr '\n' '|'; }
show() { printf '%s status=%s out=' "$1" "$2"; /usr/bin/tr '\n' '|' < /tmp/rf.out; printf ' err='; strip /tmp/rf.err; echo; }
r() { local l=$1; shift; "$@" >/tmp/rf.out 2>/tmp/rf.err; show "$l" $?; }
u() { local g=--clear-groups; [[ $3 ]] && g=--groups=$3
  /usr/bin/setpriv --reuid=2000 --regid=2000 $g -- "$BASH" --noprofile --norc -c "$2" >/tmp/rf.out 2>/tmp/rf.err; show "$1" $?; }
/usr/bin/mount --bind passwd.fixture /etc/passwd && /usr/bin/mount --bind group.fixture /etc/group || { echo SETUP-FAILED; exit 99; }
/usr/bin/touch f1 f2 f3 f4 f5 f6 f7; /usr/bin/ln -s f5 l5; /usr/bin/ln -s f6 l6
r numeric-uid chown 3001 f1
r named-uid chown bob f2
r group-only chown :3050 f3
r named-both chown alice:staff f4
r numeric-both chown 3002:3060 f7
r link-h chown -h bob:staff l5
r link-follow chown alice:other l6
r unknown-user chown nosuchuser f1
/usr/bin/stat -c '%n %u:%g' f1 f2 f3 f4 f5 l5 f6 l6 f7

