/usr/bin/mkdir -m 0777 g; /usr/bin/touch g/f1 g/f2 g/f3 g/f4 g/f5; /usr/bin/chown 2000:2000 g/f1 g/f2 g/f3 g/f4 g/f5
u named-member 'chgrp staff g/f1' 3050
u named-nonmember 'chgrp other g/f2' 3050
u numeric-member 'chgrp 3050 g/f3' 3050
u own-primary 'chgrp runner g/f4' 3050
u unknown-name 'chgrp nosuchgroup g/f5' 3050
/usr/bin/stat -c '%n %u:%g' g/f1 g/f2 g/f3 g/f4 g/f5

