printf 'kept\n' > imm; /usr/bin/chattr +i imm || echo SETUP-FAILED
echo "flags=$(/usr/bin/lsattr imm)"
r unlink-immutable unlink imm
r unlink-immutable-abs unlink "$PWD/imm"
echo "after: $(/usr/bin/ls) content=$(< imm)"
/usr/bin/chattr -i imm; echo "teardown flags=$(/usr/bin/lsattr imm)"
r unlink-cleared unlink imm
echo "final: $(/usr/bin/ls)"

strip() { /usr/bin/sed -E 's/^[^:]*: line [0-9]+: //' "$1" | /usr/bin/tr '\n' '|'; }
show() { printf '%s status=%s out=' "$1" "$2"; /usr/bin/tr '\n' '|' < /tmp/rf.out; printf ' err='; strip /tmp/rf.err; echo; }
r() { local l=$1; shift; "$@" >/tmp/rf.out 2>/tmp/rf.err; show "$l" $?; }
